import React, { useState, useRef } from 'react';
import axios from 'axios';

const EnhancedBillUpload = ({ onUploadSuccess }) => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [processingStatus, setProcessingStatus] = useState(null);
  const fileInputRef = useRef(null);

  // Check processing status on component mount
  React.useEffect(() => {
    checkProcessingStatus();
  }, []);

  const checkProcessingStatus = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/bills/processing-status', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProcessingStatus(response.data);
    } catch (error) {
      console.error('Error checking processing status:', error);
    }
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFile(e.dataTransfer.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleFileSelect = (e) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.dataTransfer.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setError('Please select a file first');
      return;
    }

    setUploading(true);
    setError(null);
    setResult(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:8000/upload',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setResult(response.data);
      setFile(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      
      // Call the success callback if provided
      if (onUploadSuccess) {
        onUploadSuccess(response.data);
      }
    } catch (error) {
      console.error('Upload error:', error);
      setError(
        error.response?.data?.detail || 
        'An error occurred while processing the bill'
      );
    } finally {
      setUploading(false);
    }
  };

  const removeFile = () => {
    setFile(null);
    setError(null);
    setResult(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="modern-bill-upload-container">
      {/* Header Section */}
      <div className="upload-header-section">
        <div className="header-content">
          <h1 className="upload-title">AI-Powered Bill Processing</h1>
          <p className="upload-subtitle">
            Upload your receipts and bills for intelligent data extraction using Gemini 2.0 Flash technology
          </p>
        </div>
      </div>

      {/* Upload Section */}
      <div className="upload-section">
        <div className="upload-card">
          <div className="upload-icon">📄</div>
          <h2 className="upload-card-title">Upload Bill or Receipt</h2>
          <p className="upload-card-subtitle">
            Drag and drop your file here or click to browse. We support JPG, PNG, and PDF formats.
          </p>
          
          <div 
            className={`file-drop-area ${dragActive ? 'drag-active' : ''}`}
            onDragEnter={handleDrag}
            onDragLeave={handleDrag}
            onDragOver={handleDrag}
            onDrop={handleDrop}
            onClick={() => fileInputRef.current?.click()}
          >
            <input
              ref={fileInputRef}
              type="file"
              onChange={handleFileSelect}
              accept=".jpg,.jpeg,.png,.pdf"
              style={{ display: 'none' }}
            />
            
            {!file ? (
              <div className="drop-zone-content">
                <div className="drop-zone-icon">📁</div>
                <p className="drop-zone-text">
                  <strong>Click to select</strong> or drag and drop your file here
                </p>
                <p className="drop-zone-hint">JPG, PNG, PDF up to 10MB</p>
              </div>
            ) : (
              <div className="file-info">
                <div className="file-icon">📄</div>
                <div className="file-details">
                  <p className="file-name">{file.name}</p>
                  <p className="file-size">{formatFileSize(file.size)}</p>
                </div>
                <button 
                  className="remove-file-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    removeFile();
                  }}
                >
                  ✕
                </button>
              </div>
            )}
          </div>

          {/* Upload Button */}
          {file && (
            <div className="upload-actions">
              <button
                className={`upload-button ${uploading ? 'uploading' : ''}`}
                onClick={handleUpload}
                disabled={uploading}
              >
                {uploading ? (
                  <>
                    <div className="upload-spinner"></div>
                    <span>Processing...</span>
                  </>
                ) : (
                  <>
                    <span className="upload-icon">🚀</span>
                    <span>Process Bill with AI</span>
                  </>
                )}
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Processing Status */}
      {processingStatus && (
        <div className="status-section">
          <h2 className="section-title">Processing Status</h2>
          <div className="status-grid">
            <div className="status-card">
              <div className="status-icon">⏳</div>
              <div className="status-content">
                <h3 className="status-label">Pending</h3>
                <p className="status-value">{processingStatus.pending || 0}</p>
              </div>
            </div>
            
            <div className="status-card">
              <div className="status-icon">🔄</div>
              <div className="status-content">
                <h3 className="status-label">Processing</h3>
                <p className="status-value">{processingStatus.processing || 0}</p>
              </div>
            </div>
            
            <div className="status-card">
              <div className="status-icon">✅</div>
              <div className="status-content">
                <h3 className="status-label">Completed</h3>
                <p className="status-value">{processingStatus.completed || 0}</p>
              </div>
            </div>
            
            <div className="status-card">
              <div className="status-icon">❌</div>
              <div className="status-content">
                <h3 className="status-label">Failed</h3>
                <p className="status-value">{processingStatus.failed || 0}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Results Section */}
      {result && (
        <div className="results-section">
          <h2 className="section-title">Processing Results</h2>
          <div className="results-card">
            <div className="result-header">
              <div className="result-icon">✨</div>
              <div className="result-title">
                <h3>Bill Successfully Processed</h3>
                <p>AI extraction completed with high accuracy</p>
              </div>
            </div>
            
            <div className="result-details">
              <div className="detail-row">
                <span className="detail-label">Bill ID:</span>
                <span className="detail-value">{result.bill_id || 'N/A'}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">Status:</span>
                <span className="detail-value success">Success</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">Processing Time:</span>
                <span className="detail-value">{result.processing_time || 'N/A'}</span>
              </div>
            </div>
            
            <div className="result-actions">
              <button className="view-details-btn">
                View Full Details
              </button>
              <button className="upload-another-btn" onClick={removeFile}>
                Upload Another Bill
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <div className="modern-message error">
          <div className="message-content">
            <span className="message-icon">⚠️</span>
            <span className="message-text">{error}</span>
          </div>
        </div>
      )}

      {/* Features Section */}
      <div className="features-section">
        <h2 className="section-title">Why Choose Our AI Processing?</h2>
        <div className="features-grid">
          <div className="feature-card">
            <div className="feature-icon">🎯</div>
            <h3 className="feature-title">High Accuracy</h3>
            <p className="feature-description">
              90%+ accuracy rate using advanced Gemini 2.0 Flash technology
            </p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon">⚡</div>
            <h3 className="feature-title">Fast Processing</h3>
            <p className="feature-description">
              Process bills in seconds with our optimized AI pipeline
            </p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon">🔒</div>
            <h3 className="feature-title">Secure & Private</h3>
            <p className="feature-description">
              Your data is encrypted and processed securely
            </p>
          </div>
          
          <div className="feature-card">
            <div className="feature-icon">📱</div>
            <h3 className="feature-title">Multi-Format</h3>
            <p className="feature-description">
              Support for JPG, PNG, and PDF files
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default EnhancedBillUpload;
